package com.studybuddy.api.domain;
import jakarta.persistence.*;
import java.time.Instant;
@Entity @Table(name="group_memberships",uniqueConstraints=@UniqueConstraint(columnNames={"group_id","user_id"}))
public class GroupMembership { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="group_id",nullable=false) private StudyGroup group; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="user_id",nullable=false) private User user; @Enumerated(EnumType.STRING) @Column(nullable=false) private MembershipStatus status=MembershipStatus.PENDING; @Column(name="is_coordinator",nullable=false) private boolean coordinator; @Column(name="created_at",nullable=false) private Instant createdAt=Instant.now(); protected GroupMembership(){} public GroupMembership(StudyGroup group,User user,MembershipStatus status,boolean coordinator){this.group=group;this.user=user;this.status=status;this.coordinator=coordinator;} public Long getId(){return id;} public StudyGroup getGroup(){return group;} public User getUser(){return user;} public MembershipStatus getStatus(){return status;} public boolean isCoordinator(){return coordinator;} public void setStatus(MembershipStatus status){this.status=status;} }
